<style>
.fx-header-icon{display:none}
.fx-product-spice .fx-spice-btn::before,.fx-product-spice .fx-spice-btn::after{content:none}
.fx-product-spice .fx-spice-levels{border:0}
.fx-purchase-bar .fx-product-add{border-radius:14px!important;padding:12px 10px!important;font-size:13px!important}
.fx-product-detail .fx-product-title{font-family:'DM Sans',sans-serif!important}
.fx-product-addons>.fx-option-heading{display:flex;flex-direction:row;border:0}
.fx-product-addons>.fx-extra-row{display:flex;flex-direction:row;border-top:0}
.fx-product-addons .fx-extra-row>label{padding:0!important;border:0!important}
.fx-delivery-options{margin:0 0 24px;padding:22px;border:1px solid var(--fx-border);border-radius:18px;background:#fff}.fx-delivery-options label{display:flex;align-items:center;gap:12px;min-height:48px;font-size:14px}.fx-delivery-options input{accent-color:var(--fx-green)}
.fx-basket-line{display:flex;gap:16px;padding:20px 0;border-bottom:1px solid var(--fx-border);margin-bottom:16px}
.fx-basket-line>a{flex:0 0 90px;height:90px;border-radius:16px;overflow:hidden;background:var(--fx-cream-deep)}.fx-basket-line img{width:100%;height:100%;object-fit:cover}
.fx-basket-copy{flex:1;min-width:0}.fx-basket-copy h2{margin:0 0 8px;font-size:18px;line-height:1.2}.fx-basket-copy p{font-size:12px;line-height:1.5;margin:6px 0}
.fx-basket-controls{display:flex;align-items:center;gap:12px;margin-top:12px}.fx-basket-controls button{width:34px;height:34px;border:0;border-radius:50%;background:#fff;cursor:pointer}.fx-basket-controls .fx-basket-remove{margin-left:auto;width:auto;background:transparent;color:var(--fx-green);font-size:12px}
.fx-basket .fx-product-location{margin:24px 0}.fx-basket-outlet{display:flex;align-items:center;gap:12px;padding:15px;cursor:pointer}.fx-basket-outlet small{display:block;color:var(--fx-muted);font-size:12px;margin-top:5px}
.fx-basket .fx-profile-recent p{font-size:12px;line-height:1.5}
.fx-profile{max-width:740px;margin:0 auto;padding:40px 22px 60px}
.fx-profile h1,.fx-profile h2,.fx-profile h3{font-family:'DM Sans',sans-serif!important}
.fx-profile-heading{margin-bottom:26px}.fx-profile-heading>span{color:var(--fx-green);font-size:11px;letter-spacing:.12em;text-transform:uppercase}
.fx-profile-heading h1{margin:10px 0;font-size:40px;line-height:1.1;letter-spacing:-.045em}.fx-profile p{color:var(--fx-muted)}
.fx-profile-identity{display:flex;align-items:center;gap:16px;padding:24px;background:#fff;border-radius:20px}.fx-profile-avatar{display:grid;place-items:center;flex:0 0 58px;height:58px;border-radius:50%;background:var(--fx-cream);color:var(--fx-green);font-size:26px}
.fx-profile-identity h2{margin:0 0 6px;font-size:20px}.fx-profile-identity p{margin:3px 0;font-size:13px;overflow-wrap:anywhere}
.fx-profile-actions{margin:22px 0;padding:0 20px;border-radius:20px;background:#fff}.fx-profile-actions a{display:flex;align-items:center;gap:14px;padding:18px 0;text-decoration:none;border-bottom:1px solid var(--fx-border)}.fx-profile-actions a:last-child{border:0}
.fx-profile-action-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:var(--fx-cream);color:var(--fx-green);font-size:22px}.fx-profile-actions a>span:nth-child(2){flex:1;min-width:0}.fx-profile-actions strong{display:block;font-size:15px;font-weight:600}.fx-profile-actions small{display:block;margin-top:4px;color:var(--fx-muted);font-size:12px}.fx-profile-actions b{font-size:22px;font-weight:400}
.fx-profile-recent{padding:22px;border-radius:20px;background:#fff}.fx-profile-section-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.fx-profile-section-heading h2{margin:0;font-size:19px}.fx-profile-section-heading a,.fx-profile-back{color:var(--fx-green);font-size:12px;text-decoration:none}
.fx-profile-empty{padding:30px 5px 10px;text-align:center}.fx-profile-empty h3,.fx-profile-empty h2{font-size:21px;line-height:1.2}.fx-profile-empty p{font-size:14px;line-height:1.6;margin:12px auto 22px;max-width:300px}
.fx-profile-cta{display:flex;align-items:center;justify-content:center;gap:18px;width:fit-content;min-height:48px;margin:20px auto 0;padding:12px 22px;background:var(--fx-green-deep);color:#fff!important;border-radius:14px;text-decoration:none;font-size:14px}.fx-profile-signout{display:block;margin-top:28px;text-align:center;color:var(--fx-green)!important;font-size:14px}
.fx-order-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 0;border-bottom:1px solid var(--fx-border)}.fx-order-row:last-child{border:0}.fx-order-row small{display:block;margin-top:5px;color:var(--fx-muted);font-size:12px}.fx-order-row b{font-size:14px;white-space:nowrap}.fx-order-status{display:inline-block;margin-top:8px;font-size:12px;color:var(--fx-green)}
.fx-option-heading{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:14px}.fx-option-heading h2,.fx-option-heading label{margin:0;font-family:'DM Sans',sans-serif!important;font-size:18px;font-weight:700;letter-spacing:-.025em}.fx-option-heading small{color:var(--fx-muted);font-size:12px;font-weight:400;white-space:nowrap}
.fx-product-spice .fx-spice-levels{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.fx-product-spice .fx-spice-btn{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;min-width:0;min-height:74px;padding:12px 5px;border:1px solid var(--fx-border);border-radius:15px;background:var(--fx-cream);color:var(--fx-ink);font-size:12px}.fx-product-spice .fx-spice-btn.active{background:var(--fx-green-deep);border-color:var(--fx-green-deep);color:#fff}.fx-heat-mark{font-size:9px;letter-spacing:2px;color:var(--fx-green)}.fx-spice-btn.active .fx-heat-mark{color:var(--fx-yellow)}.fx-spice-btn:focus-visible{outline:2px solid var(--fx-green);outline-offset:3px}
.fx-extra-row{display:flex;align-items:center;gap:10px;padding:16px 0;border-bottom:1px solid var(--fx-border)}.fx-product-addons .fx-extra-row>label{display:flex;align-items:center;flex:1;gap:12px;margin:0;font-size:14px;cursor:pointer}.fx-extra-row input[type=checkbox]{width:22px;height:22px;margin:0;flex-shrink:0;accent-color:var(--fx-green-deep)}.fx-extra-price{color:var(--fx-green);font-size:13px;white-space:nowrap}.fx-extra-qty{width:50px;padding:7px;border:1px solid var(--fx-border);border-radius:8px;background:#fff}
.fx-product-instructions textarea{width:100%;min-height:88px;padding:14px;border:1px solid var(--fx-border);border-radius:14px;background:#fff;color:var(--fx-ink);font:inherit;font-size:14px;resize:vertical}.fx-product-instructions p{margin:8px 0 0;color:var(--fx-muted);font-size:11px;line-height:1.5}
.fx-purchase-bar{display:flex;align-items:center;gap:12px;padding:16px 0;background:var(--fx-cream)}.fx-purchase-bar .fx-product-quantity{margin:0;flex:0 0 auto}.fx-purchase-bar .fx-quantity-control{display:flex;border:1px solid var(--fx-border);border-radius:14px;overflow:hidden}.fx-purchase-bar .fx-product-add{position:static;min-width:0;min-height:52px;margin:0;flex:1;padding:14px 10px;border-radius:14px;font-size:13px;text-transform:none;letter-spacing:0;color:#fff!important;background:var(--fx-green-deep)!important}
@media(max-width:820px){
.fx-meal-page{padding-top:16px!important}.fx-meal-page nav[aria-label=Breadcrumb]{display:none}
.fx-header--meal .fx-location{display:none!important}.fx-header--meal .fx-header-top{grid-template-areas:'brand actions'}
.fx-meal-page .fx-product-hero-image{height:260px;min-height:0}.fx-meal-page .fx-product-gallery{min-height:0}
.fx-meal-page .fx-product-info{top:auto}
.fx-checkout-layout{display:block!important}.fx-checkout-layout>div:last-child{position:static!important;margin-top:24px}
.fx-header-actions{gap:4px}.fx-header .fx-header-icon{display:inline-flex;align-items:center;justify-content:center;width:36px;height:40px;padding:8px;background:transparent;border:0;color:#fff}.fx-header .fx-logo-name{max-width:100%;white-space:normal;font-size:15px!important;line-height:1.15}.fx-header .fx-logo-img{width:30px;height:30px;flex-basis:30px}.fx-header .fx-logo{gap:7px}.fx-header .fx-cart-btn{width:36px!important;height:40px!important}
.fx-header .fx-header-search{display:none!important}.fx-header .fx-header-search.is-open{display:block!important;margin-top:12px}.fx-header--account .fx-location{display:none!important}.fx-header--account .fx-header-top{grid-template-areas:'brand actions'}.fx-nav{display:none}.fx-nav.fx-nav-menu{display:block}
.fx-profile{padding:28px 18px 40px}.fx-profile-heading h1{font-size:32px}.fx-profile-identity{padding:20px 16px}.fx-profile-identity h2{font-size:18px}.fx-profile-recent{padding:20px 16px}
.fx-purchase-bar{position:sticky;bottom:86px;z-index:15;margin:0 -4px;padding:12px 4px}.fx-purchase-bar .fx-product-add{box-shadow:none}.fx-purchase-bar .fx-quantity-control button{width:32px!important}.fx-purchase-bar .fx-quantity-control input{width:34px!important}.fx-product-option{margin-bottom:26px!important}.fx-product-detail .fx-product-info{padding-bottom:28px}.fx-product-info .fx-product-title{font-size:30px!important;line-height:1.08!important;letter-spacing:-.04em}.fx-product-info .fx-product-price{padding:0!important;margin:14px 0 26px;border:0}.fx-product-info .fx-product-whatsapp{margin-top:8px;min-height:44px}
}
</style>
